def decide(recipient_reputation, round_num, my_history):
    # Base threshold becomes more conservative as rounds progress
    base_threshold = 0.2 - 0.3 * (round_num / 10)  # ranges from 0.2 down to -0.1
    # Adjust based on own recent cooperations (acts of personal goodwill)
    recent_coop = sum(1 for entry in my_history[-2:] if entry['action'] == 'cooperate')
    if recent_coop == 2:
        # Very cooperative mood -> more forgiving
        threshold = base_threshold - 0.2
    elif recent_coop == 1:
        threshold = base_threshold
    else:  # defected at least twice recently -> more demanding
        threshold = base_threshold + 0.2
    return recipient_reputation > threshold
